import React, { ReactElement } from "react";
import styled from "styled-components";

import { InlineAlert } from "@mendix/ide-ui-components/alert/index";
import { AlertType } from "@mendix/ide-ui-components/alert/alertHelpers";

import { InformationIcon } from "@mendix/ide-icons/InformationIcon";
import { WarningIcon } from "@mendix/ide-icons/WarningIcon";
import { ErrorIcon } from "@mendix/ide-icons/ErrorIcon";
import { CheckmarkIcon } from "@mendix/ide-icons/CheckmarkIcon";

interface BannerProps {
    children: React.ReactNode;
    onClose?: () => void;
}

interface BaseBannerProps extends BannerProps {
    type: AlertType;
    icon: ReactElement;
}

const AlertWrapper = styled.div`
    [role="alert"] {
        align-items: start;
        padding: 8px 8px;
        & > button {
            padding: 0px;
        }
        & > div {
            padding: 0px;
        }
        ul {
            margin-block-start: 8px;
            margin-block-end: 0px;
            padding: 0px 0px 0px 18px;
        }
    }
`;

const BaseBanner: React.FC<BaseBannerProps> = ({ children, type, icon, onClose }) => {
    return (
        <AlertWrapper>
            <InlineAlert type={type} icon={icon} onClose={onClose}>
                {children}
            </InlineAlert>
        </AlertWrapper>
    );
};

export const InfoBanner: React.FC<BannerProps> = (props) => (
    <BaseBanner {...props} type="info" icon={<InformationIcon />} />
);

export const WarningBanner: React.FC<BannerProps> = (props) => (
    <BaseBanner {...props} type="warning" icon={<WarningIcon />} />
);

export const ErrorBanner: React.FC<BannerProps> = (props) => (
    <BaseBanner {...props} type="danger" icon={<ErrorIcon />} />
);

export const SuccessBanner: React.FC<BannerProps> = (props) => (
    <BaseBanner {...props} type="success" icon={<CheckmarkIcon />} />
);
